// ReportView.js
import React, { useState, useEffect, }  from 'react';
import { Button, Form, Modal, Dropdown } from 'react-bootstrap';
import { ArrowUp,ArrowDown} from 'react-bootstrap-icons';
function ReportView({  activeCollection, // Collect activeCollection prop
updateActiveCollection  }) {

  const [segments, setSegments] = useState([]);
  const [name, setName] = useState('');
  const [pronoun, setPronoun] = useState('');
  const [finalComment, setFinalComment] = useState([]);
  const [includedSegments, setIncludedSegments] = useState(segments.map(() => false));
  const [showCopyConfirmation, setShowCopyConfirmation] = useState(false);

  const [showBulkImportModal, setShowBulkImportModal] = useState(false);
  const [bulkImportData, setBulkImportData] = useState([]);
  const [currentImportIndex, setCurrentImportIndex] = useState(0);
  const [levelLabels, setLevelLabels] = useState([]);

  // New state for tracking selected text index in each segment and level
  const [selectedTextIndices, setSelectedTextIndices] = useState([]);
  const [isSegmentMoved, setIsSegmentMoved] = useState(false);


  useEffect(() => {
    let loadedCollections = JSON.parse(localStorage.getItem('collections')) || {};
    if (loadedCollections[activeCollection]) {
      const newSegments = loadedCollections[activeCollection].segments || [];
      const newLevelLabels = loadedCollections[activeCollection].levelLabels || ["Level 1", "Level 2", "Level 3"];
      setSegments(newSegments);
      setLevelLabels(newLevelLabels);
      setIncludedSegments(newSegments.map(() => true)); // Initialize includedSegments based on newSegments
      generateComment(newSegments); // Generate comment based on new segments
    }
  }, [activeCollection]); // Depend on activeCollection

  useEffect(() => {
    let loadedCollections = JSON.parse(localStorage.getItem('collections')) || {};
  
    // Ensure 'My Comments' collection exists
    if (!loadedCollections.hasOwnProperty('My Comments')) {
      loadedCollections['My Comments'] = {
        segments: [],
        levelLabels: ["Level 1", "Level 2", "Level 3"]
      };
      localStorage.setItem('collections', JSON.stringify(loadedCollections));
      updateActiveCollection("My Comments");
    }
  
    if (activeCollection && loadedCollections[activeCollection]) {
      setSegments(loadedCollections[activeCollection].segments || []);
    } else {
      setSegments([]);
    }
  }, [activeCollection, updateActiveCollection]);
  
  useEffect(() => {
    let loadedCollections = JSON.parse(localStorage.getItem('collections')) || {};
    if (loadedCollections[activeCollection]) {
      const newSegments = loadedCollections[activeCollection].segments || [];
      setSegments(newSegments);
      setIncludedSegments(newSegments.map(() => false)); // Initialize includedSegments based on newSegments
      generateComment(newSegments); // Generate comment based on new segments
    }
  }, [activeCollection]); // Depend on activeCollection
  
  useEffect(() => {
    generateComment(); // This will run every time includedSegments changes
  }, [includedSegments]); // Add includedSegments as a dependency

  useEffect(() => {
    // Initialize selectedTextIndices based on the segments
    setSelectedTextIndices(segments.map(() => ({ level: 0, textIndex: 0 })));

  }, [segments]);

// useEffect to generate comment when selectedTextIndices changes
useEffect(() => {
  generateComment();
}, [selectedTextIndices]);
  
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === 'ArrowRight') {
        setCurrentImportIndex(prevIndex => {
          const nextIndex = prevIndex + 1 < bulkImportData.length ? prevIndex + 1 : prevIndex;
          updateNameAndPronoun(nextIndex);
          return nextIndex;
        });
      } else if (event.key === 'ArrowLeft') {
        setCurrentImportIndex(prevIndex => {
          const nextIndex = prevIndex - 1 >= 0 ? prevIndex - 1 : prevIndex;
          updateNameAndPronoun(nextIndex);
          return nextIndex;
        });
      }
    };
  
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [bulkImportData]); // Re-run effect when bulkImportData changes
  
// Handler for level selection
const handleLevelSelection = (segmentIndex, level) => {
  setSelectedTextIndices(prevIndices => {
    const updatedIndices = [...prevIndices];
    updatedIndices[segmentIndex] = { level, textIndex: 0 }; // Reset text index to 0
    return updatedIndices;
  });
};

// Handler for text selection within a level
const handleTextSelection = (segmentIndex, textIndex) => {
  setSelectedTextIndices((prevIndices) => {
    const updatedIndices = [...prevIndices];
    updatedIndices[segmentIndex] = {
      ...updatedIndices[segmentIndex],
      textIndex: textIndex,
    };
    return updatedIndices;
  });

  // Set the corresponding segment to be included
  setIncludedSegments((prevIncluded) => {
    const updatedIncluded = [...prevIncluded];
    updatedIncluded[segmentIndex] = true; // Turn on the segment
    return updatedIncluded;
  });
};



  const updateNameAndPronoun = (index) => {
    if (bulkImportData.length > index) {
      setName(bulkImportData[index].name);
      setPronoun(bulkImportData[index].pronoun);
    }
    // Turn off all segments when switching names/pronouns
    setIncludedSegments(segments.map(() => false));

  };
  

  const formatCommentTextForClipboard = () => {
    const spReplacement = pronoun === 'they' ? 'they' : pronoun === 'he' ? 'he' : 'she';
    const ppReplacement = pronoun === 'they' ? 'their' : pronoun === 'he' ? 'his' : 'her';
    const hhtReplacement = pronoun === 'they' ? 'them' : pronoun === 'he' ? 'him' : 'her';
  
    return finalComment.map((commentSegment) => {
      return commentSegment.text
        .replace(/%nn/g, name)
        .replace(/\s*%Nn('?s)?/g, match => {
          if (match === "%Nn" || match === "%Nn's") {
            return capitalize(name) + match.slice(3);
          } else {
            return capitalize(name) + match.slice(4);
          }
        })
        .replace(/%sp/g, spReplacement)
        .replace(/%Sp/g, capitalize(spReplacement))
        .replace(/%pp/g, ppReplacement)
        .replace(/%Pp/g, capitalize(ppReplacement))
        .replace(/%hht/g, hhtReplacement);
    }).join(' ');
  };
  
  
    
  const copyToClipboard = () => {
    const textToCopy = formatCommentTextForClipboard();
    navigator.clipboard.writeText(textToCopy).then(function() {
      setShowCopyConfirmation(true); // Show confirmation
      setTimeout(() => {
        setShowCopyConfirmation(false); // Hide confirmation after 2 seconds
      }, 2000);
    }, function(err) {
      alert('Failed to copy text: ', err);
    });
  };
  const parseBulkImportData = (data) => {
    const lines = data.split('\n');
    const parsedData = lines.map(line => {
      const [name, pronoun] = line.split('\t'); // Assuming tab-separated values
      return { name, pronoun };
    });
    setBulkImportData(parsedData);
    if (parsedData.length > 0) {
      setName(parsedData[0].name);
      setPronoun(parsedData[0].pronoun);
    }
  };
  const replacePlaceholders = (text, name, pronoun) => {
    if (!name || !pronoun) {
      return text; // Return the original text if name or pronoun is not set
    }
    const spReplacement = pronoun === 'they' ? 'they' : pronoun === 'he' ? 'he' : 'she';
    const ppReplacement = pronoun === 'they' ? 'their' : pronoun === 'he' ? 'his' : 'her';
    const hhtReplacement = pronoun === 'they' ? 'them' : pronoun === 'he' ? 'him' : 'her';
  
    return text
      .replace(/%nn/g, name)
      .replace(/\s*%Nn('?s)?/g, match => {
        if (match === "%Nn" || match === "%Nn's") {
          return capitalize(name) + match.slice(3);
        } else {
          return capitalize(name) + match.slice(4);
        }
      })
      .replace(/%sp/g, spReplacement)
      .replace(/%Sp/g, capitalize(spReplacement))
      .replace(/%pp/g, ppReplacement)
      .replace(/%Pp/g, capitalize(ppReplacement))
      .replace(/%hht/g, hhtReplacement);
  };

    const setLevel = (newLevel, index) => {
      const newSegments = [...segments];
      newSegments[index].level = newLevel;
      setSegments(newSegments);
      generateComment()
      };
      

      const updateText = (commentIndex) => {
        const commentSegment = finalComment[commentIndex];
        const levelTexts = segments[commentSegment.segmentIndex].levelTexts[commentSegment.level];
        const newTextIndex = (commentSegment.textIndex + 1) % levelTexts.length;
        const newComment = [...finalComment];
        newComment[commentIndex].text = levelTexts[newTextIndex];
        newComment[commentIndex].textIndex = newTextIndex;
        setFinalComment(newComment);
      }
    
      

      const generateComment = () => {
        let newComment = segments
    
          .map((segment, i) => {
            if (!includedSegments[i]) return null; // Skip segments that are not included
            const selectedText = selectedTextIndices[i];
            const levelIndex = selectedText ? selectedText.level : segment.level;
            const levelTexts = segment.levelTexts[levelIndex];
            let textIndex = selectedText && selectedText.textIndex !== undefined
                            ? selectedText.textIndex
                            : Math.floor(Math.random() * levelTexts.length);
            let text = levelTexts[textIndex] || "";
      
            return { text, segmentIndex: i, level: levelIndex, textIndex };
          })
          .filter(segment => segment !== null); // Remove null entries representing excluded segments
      
        setFinalComment(newComment);
      };
      
      
    
    const formatCommentText = () => {
      const spReplacement = pronoun === 'they' ? 'they' : pronoun === 'he' ? 'he' : 'she';
      const ppReplacement = pronoun === 'they' ? 'their' : pronoun === 'he' ? 'his' : 'her';
      const hhtReplacement = pronoun === 'they' ? 'them' : pronoun === 'he' ? 'him' : 'her';
      
      return finalComment.map((commentSegment, i) => {
        const text = commentSegment.text
        .replace(/%nn/g, name)
        .replace(/\s*%Nn('?s)?/g, match => {
          if (match === "%Nn" || match === "%Nn's") {
            return capitalize(name) + match.slice(3);
          } else {
            return capitalize(name) + match.slice(4);
          }
        })
        .replace(/%sp/g, spReplacement)
        .replace(/%Sp/g, capitalize(spReplacement))
        .replace(/%pp/g, ppReplacement)
        .replace(/%Pp/g, capitalize(ppReplacement))
        .replace(/%hht/g, hhtReplacement);
    
        return (
          <span 
            key={i} 
            style={{ margin: '0 5px' }} 
            onMouseEnter={(e) => e.target.style.border = '2px dotted red'} 
            onMouseLeave={(e) => e.target.style.border = ''}
            onClick={() => updateText(i)}
          >
            {text}
          </span>
        );
      });
    }
    
    const capitalize = (s) => {
      if (typeof s !== 'string') return ''
      return s.charAt(0).toUpperCase() + s.slice(1)
    }

    // Function to swap elements in an array
const swapArrayElements = (arr, index1, index2) => {
  const newArr = [...arr];
  [newArr[index1], newArr[index2]] = [newArr[index2], newArr[index1]];
  return newArr;
};

const moveSegmentUp = (index) => {
  if (index === 0) return;

  
  setIncludedSegments(included => swapArrayElements(included, index, index - 1));
  setSegments(segments => swapArrayElements(segments, index, index - 1));
  console.log(selectedTextIndices)
  setSelectedTextIndices(indices => swapArrayElements(indices, index, index - 1));
  console.log(selectedTextIndices)
};

const moveSegmentDown = (index) => {
  if (index === segments.length - 1) return;

  
  setIncludedSegments(included => swapArrayElements(included, index, index + 1));
  setSegments(segments => swapArrayElements(segments, index, index + 1));
  
  setSelectedTextIndices(indices => swapArrayElements(indices, index, index + 1));

};

    
      
  return (
    <div>
      

    <Form>
      
      <Form.Group>
      <Button variant="primary" onClick={() => setShowBulkImportModal(true)}>Bulk Import</Button><p></p>
        <Form.Label>Name</Form.Label>
        <Form.Control type="text" value={name} onChange={e => setName(e.target.value)} />
     
      </Form.Group>

      <Form.Group>
        <Form.Label>Pronoun</Form.Label>
        <Form.Control as="select" value={pronoun} onChange={e => setPronoun(e.target.value)}>
          <option value="">--Please choose an option--</option>
          <option value="he">He</option>
          <option value="she">She</option>
          <option value="they">They</option>
        </Form.Control>
      </Form.Group>

      <hr />

      {segments.map((segment, i) => (
  <div className="card mb-3" key={i}>
    <div className="card-body">
      <div className="row align-items-center">
        {segment.title}
        <div className="col">

        {levelLabels.map((label, levelIndex) => (
  <Dropdown key={levelIndex}>
    <Dropdown.Toggle 
      variant="secondary" 
      id={`dropdown-${i}-${levelIndex}`}
      className={`${selectedTextIndices[i] && selectedTextIndices[i].level === levelIndex ? 'bg-primary text-white' : ''}`}
    >
      {label}
    </Dropdown.Toggle>

    <Dropdown.Menu className="dropdown-menu-end">
      {segment.levelTexts[levelIndex].map((text, textIndex) => (
        <Dropdown.Item
          key={textIndex}
          onClick={(e) => {
            e.preventDefault();
            handleLevelSelection(i, levelIndex);
            handleTextSelection(i, textIndex);
          }}
        >
          {replacePlaceholders(text, name, pronoun)}
        </Dropdown.Item>
      ))}
    </Dropdown.Menu>
  </Dropdown>
))}

        </div>
        <div className="col-auto">
          <Form.Check
            type="switch"
            id={`include-switch-${i}`}
            label=""
            checked={includedSegments[i]}
            onChange={e => {
              const updatedIncludedSegments = [...includedSegments];
              updatedIncludedSegments[i] = e.target.checked;
              setIncludedSegments(updatedIncludedSegments);
              generateComment(); // Regenerate comment whenever a segment is toggled
            }}
            
          />
        </div>
        <div className="col-auto">
          <div className="d-flex flex-column justify-content-center">
            <ArrowUp onClick={() => moveSegmentUp(i)} style={{ cursor: 'pointer' }} />
            <ArrowDown onClick={() => moveSegmentDown(i)} style={{ cursor: 'pointer', marginTop: '5px' }} />
          </div>
        </div>
      </div>
    </div>
  </div>
  
))}




      <Button variant="primary" onClick={generateComment} className = "mt-3">Generate Comment</Button>
<Button variant="secondary" onClick={copyToClipboard} className = "mt-3 ml-3">Copy to Clipboard</Button>
{showCopyConfirmation && (
  <div style={{
    position: 'fixed', // Fixed position
    bottom: '20px', // Positioned at the bottom
    right: '20px', // Positioned to the right
    backgroundColor: 'lightgreen', // A light green background to signify success
    padding: '10px', // Some padding around the text
    borderRadius: '5px', // Rounded corners
    boxShadow: '0 2px 4px rgba(0,0,0,0.2)' // A subtle shadow
  }}>
    Comment copied to clipboard!
  </div>
)}

      <Form.Group className="mt-3">
        <Form.Label>Final Comment</Form.Label>
        <div className="border p-3">
          {formatCommentText()}
        </div>
      </Form.Group>
    </Form>

    <Modal show={showBulkImportModal} onHide={() => setShowBulkImportModal(false)}>
  <Modal.Header closeButton>
    <Modal.Title>Bulk Import Names and Pronouns</Modal.Title>
  </Modal.Header>
  <Modal.Body>
    <Form.Control
      as="textarea"
      rows="10"
      placeholder="Paste names and pronouns here, separated by tabs"
      onChange={e => parseBulkImportData(e.target.value)}
    />
  </Modal.Body>
</Modal>

    </div>
  );
 
}

export default ReportView;
